  if (reading) choices.push(renderDialogueChoice(actionHref(reading, output?.context?.origin || origin), "関連する背景を確認", "Readingで一般的な研究背景を見る"));
  return renderDialogueFrame({
    output,
    title: "次回に活かす",
    message: "次回に向けて、予定・共有・背景確認のどれを使うか選べます。",
